import { createSlice } from "@reduxjs/toolkit";
/**
 * An example of creating feature slices, reducers and INITIAL_STATE.
 */

const INITIAL_STATE = {
  baseUrl: process.env.REACT_BASE_URL || "",
  state: {
    isLoading: false,
    error: null,
  },
  apiStatus: {
    statusCode: null,
    statusText: null,
    data: null,
  },
};

export const favoriteResourcesFeatureSlice = createSlice({
  // A name, used in action types
  name: "favoriteResources",
  // The initial state for the reducer
  initialState: INITIAL_STATE,
  // An object of "case reducers". Key names will be used to generate actions.
  reducers: {
    toggleGetFavoriteResources: (state) => {
      state.state.isLoading = true;
    },
    toggleGetFavoriteResourcesSuccess: (state, action) => ({
      ...state,
      state: {
        ...state.state,
        error: null,
        isLoading: false,
      },
      apiStatus: {
        ...state.apiStatus,
        statusCode: action.payload?.statusCode,
        statusText: action.payload?.statusText,
        data: action.payload?.data,
      },
    }),
    toggleGetFavoriteResourcesFailure: (state, action) => ({
      ...state,
      state: {
        ...state.state,
        error: action.payload?.message,
        isLoading: false,
      },
      apiStatus: {
        ...state.apiStatus,
        statusCode: action.payload?.statusCode,
        statusText: action.payload?.statusText,
        data: null,
      },
    }),
    toggleClearFavoriteResources: (state) => ({
      ...state,
      state: {
        ...state.state,
        error: null,
        isLoading: false,
      },
      apiStatus: {
        ...state.apiStatus,
        statusCode: null,
        statusText: null,
        data: null,
      },
    }),
    togglePostFavoriteResourcesStatus: (state) => {
      state.state.isLoading = true;
    },
    togglePostFavoriteResourcesStatusSuccess: (state, action) => ({
      ...state,
      state: {
        ...state.state,
        error: null,
        isLoading: false,
      },
      apiStatus: {
        ...state.apiStatus,
        statusCode: action.payload?.statusCode,
        statusText: action.payload?.statusText,
      },
    }),
    togglePostFavoriteResourcesStatusFailure: (state, action) => ({
      ...state,
      state: {
        ...state.state,
        error: action.payload?.message,
        isLoading: false,
      },
      apiStatus: {
        ...state.apiStatus,
        statusCode: action.payload?.statusCode,
        statusText: action.payload?.statusText,
      },
    }),
    togglePostBookResources: (state) => {
      state.state.isLoading = true;
    },
    togglePostBookResourcesSuccess: (state, action) => ({
      ...state,
      state: {
        ...state.state,
        error: null,
        isLoading: false,
      },
      apiStatus: {
        ...state.apiStatus,
        statusCode: action.payload?.statusCode,
        statusText: action.payload?.statusText,
      },
    }),
    togglePostBookResourcesFailure: (state, action) => ({
      ...state,
      state: {
        ...state.state,
        error: action.payload?.message,
        isLoading: false,
      },
      apiStatus: {
        ...state.apiStatus,
        statusCode: action.payload?.statusCode,
        statusText: action.payload?.statusText,
      },
    }),
  },
  // A "builder callback" function used to add more reducers
});

export const {
  toggleClearFavoriteResources,
  toggleGetFavoriteResources,
  toggleGetFavoriteResourcesFailure,
  toggleGetFavoriteResourcesSuccess,
  togglePostFavoriteResourcesStatus,
  togglePostFavoriteResourcesStatusFailure,
  togglePostFavoriteResourcesStatusSuccess,
  togglePostBookResources,
  togglePostBookResourcesFailure,
  togglePostBookResourcesSuccess,
} = favoriteResourcesFeatureSlice.actions;
export const favoriteResourcesFeatureReducer =
  favoriteResourcesFeatureSlice.reducer;
