import { AxiosResponse } from "axios";
import { call, put, takeLatest } from "redux-saga/effects";
import { Notification } from "src/components";
import { AppService } from "src/services/app";
import { ELASTIC_SEARCH_REQUESTS } from "../request-types";
import {
  toggleGetElasticSearchFailure,
  toggleGetElasticSearchSuccess,
} from "../slices/features/elastic-search";

const authService = new AppService();

function* fetchGetElasticSearch(action: any) {
  const { payload } = action;
  const { query } = payload;
  try {
    const baseUrl: any = process.env.REACT_APP_BASE_URL;

    const response: AxiosResponse<any> = yield call(
      authService.getElasticSearch,
      baseUrl,
      query
    );

    yield put(toggleGetElasticSearchSuccess({ ...response }));

    payload?.cbSuccess && payload?.cbSuccess({ ...response.data });
  } catch (errors: any) {
    const error = errors?.data?.errors || errors;

    const { statusCode, statusText } = error;
    Notification({
      type: "error",
      message: errors?.data?.errors?.message || errors?.data?.message,
    });

    payload?.cbFailure &&
      payload?.cbFailure(
        errors?.data?.errors?.message || errors?.data?.message
      );

    yield put(toggleGetElasticSearchFailure({ statusCode, statusText }));
  }
}

export function* watchGetElasticSearch() {
  yield takeLatest(
    ELASTIC_SEARCH_REQUESTS.GET_ELASTIC_SEARCH_REQUEST,
    fetchGetElasticSearch
  );
}
